# Regex to find the content inside HREF="..." and the text between > and </A>
pattern = r'HREF="([^"]*)"[^>]*>(.*?)</a>'

matches = re.findall(pattern, data, re.IGNORECASE)

for url, title in matches:
    print(f"{title} -- {url}")